<template>
  <div v-if="start_timer" class="lockout-warning">
    <Icon icon="mdi:lock-clock" class="size-4 shrink-0" />
    <span>{{ $t('failed_login_attempts_warning') }}</span>
    <span class="lockout-timer" ref="timerDisplay"></span>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

export default defineComponent({
  name: 'PasswordDisableCounter',
  props: {
    start_timer: {
      type: Boolean,
      default: false,
    },
    counter_end_time: {
      type: String,
      default: '',
    },
  },
  emits: ['disableTimerDone'],
  watch: {
    start_timer: {
      handler(newVal: boolean) {
        if (newVal) {
          this.setCounter();
        } else {
          this.hideCounter();
        }
      },
    },
  },
  mounted() {
    this.initView();
  },
  beforeUnmount() {
    if (this.counter_interval) {
      clearInterval(this.counter_interval);
      this.counter_interval = null;
    }
  },
  methods: {
    initView() {
      this.setCounter();
    },

    makeCounter() {
      const timerEl = this.$refs.timerDisplay as HTMLElement;
      if (!timerEl) return;

      if (this.counter_interval) {
        clearInterval(this.counter_interval);
      }

      const update = () => {
        const now = Date.now();
        const deadline = new Date(this.counter_dateTime).getTime();
        const totalSeconds = Math.max(0, Math.floor((deadline - now) / 1000));

        timerEl.textContent = this.formatSecondsToMinSec(totalSeconds);

        if (totalSeconds <= 0) {
          clearInterval(this.counter_interval);
          this.timeCompleted();
        }
      };

      update();
      this.counter_interval = setInterval(update, 1000);
    },

    formatSecondsToMinSec(seconds: number) {
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}m ${secs}s`;
    },

    timeCompleted() {
      this.$emit('disableTimerDone');
    },

    hideCounter() {
      const timerEl = this.$refs.timerDisplay as HTMLElement;
      if (timerEl) {
        timerEl.textContent = '';
      }

      if (this.counter_interval) {
        clearInterval(this.counter_interval);
        this.counter_interval = null;
      }
    },

    getDistance() {
      const now = new Date().getTime();
      return this.counter_time - now;
    },

    setCounter() {
      try {
        if (this.start_timer === false) return;
        this.counter_dateTime = new Date(this.counter_end_time);
        this.counter_time = this.counter_dateTime.getTime();
        const distance = this.getDistance();

        if (distance < 0) {
          this.expired_tries++;
        }
        this.makeCounter();
      } catch (err) {
        // Silent fail for counter
      }
    },
  },
  setup() {
    return {
      counter_value: ref(''),
      counter_time: ref(0),
      counter_dateTime: ref({} as Date),
      counter_interval: ref(0 as any),
      expired_tries: ref(0),
    };
  },
});
</script>

